Register-ScheduledTask -TaskName "LimpiezaCarpetasUsuario" -Trigger (New-ScheduledTaskTrigger -AtLogOn) -Action (New-ScheduledTaskAction -Execute "powershell.exe" -Argument '-WindowStyle Hidden -Command "Remove-Item -Path \"$HOME\Downloads\*\", \"$HOME\Documents\*\" -Recurse -Force -ErrorAction SilentlyContinue; Get-ChildItem -Path \"$HOME\Desktop\" -Exclude *.lnk, *.url | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue"') -Principal (New-ScheduledTaskPrincipal -GroupId "BUILTIN\Users") -Force
